/*
 * The Scala <-> Apple contract of thicket-device-apple (#114): the app's lifecycle and permissions.
 *
 * GENERATED by tools/shim-gen from thicket.tools.shim.DeviceAbi. Do not edit by hand: edit
 * tools/shim-gen/src/main/scala/thicket/tools/shim/DeviceAbi.scala and run `sbt shimGen/run`.
 * `sbt shimGen/test` fails while this file, DeviceShim.scala, DeviceShim.swift and DeviceAbi disagree.
 *
 * PUSH, ON THE MAIN THREAD ONLY. Every callback is called on the main thread: the observers are
 * registered on the main queue, and a permission's answer is moved there before it is delivered.
 * Permissions are thicket.device.Permission's ordinals: 0 Location, 1 Camera, 2 Microphone,
 * 3 Notifications. A status is 0 granted, 1 denied, 2 restricted, 3 not yet asked, -1 not
 * supported by this build.
 */
#ifndef THICKET_DEVICE_H
#define THICKET_DEVICE_H

#include <stdint.h>

typedef void (*thk_dev_void_cb)(int64_t ctx);
typedef void (*thk_dev_int_cb)(int64_t ctx, int32_t value);

/* --- lifecycle --------------------------------------------------------------- */
/* Starts following the app on and off screen and returns where it is now: 1 on screen, 0 not.
   `changed` is called on the main thread with 1 or 0 at each change after that. iOS: a scene
   entering the foreground, and the last one entering the background. macOS: NSApp's occlusion
   state, so a hidden app, a minimised window or a covered one is off screen. Once per process. */
int32_t thk_dev_lifecycle_start(thk_dev_int_cb changed, int64_t ctx);
/* Calls `terminating` on the main thread on the platform's will-terminate notification.
   Once per process. iOS rarely sends it; macOS sends it from NSApp.terminate. */
void thk_dev_on_terminate(thk_dev_void_cb terminating, int64_t ctx);

/* --- permissions ------------------------------------------------------------- */
/* What the app must declare before it may ask, or "" when nothing is missing: an Info.plist
   usage key (iOS terminates an app that asks without one), or an app bundle (notifications).
   A string that lives as long as the process. */
const char *thk_dev_permission_missing(int32_t permission);
/* The answer as it stands, without asking. Waits for UserNotifications' answer, a few ms,
   so Scala marks the call blocking. */
int32_t thk_dev_permission_status(int32_t permission);
/* Asks the user (the system shows its dialog only while the answer is not yet given) and calls
   `answered` with the resulting status, always later, on the main thread. */
void thk_dev_permission_request(int32_t permission, thk_dev_int_cb answered, int64_t ctx);

/* --- testing ----------------------------------------------------------------- */
/* For self-tests: what a user would do. */
/* macOS: hides (1) or unhides (0) the app, as Cmd-H does. Returns 1, or 0 on iOS, where an
   app cannot leave the screen by itself. */
int32_t thk_dev_test_hide(int32_t hidden);
/* macOS: minimises (1) or restores (0) the app's visible windows. Returns how many, 0 on iOS. */
int32_t thk_dev_test_miniaturize(int32_t miniaturized);
/* macOS: NSApp.terminate, the real path; the process exits after the will-terminate
   observers run. iOS: posts UIApplication.willTerminateNotification, since an app may not
   end itself and simctl's terminate kills it without one. */
void thk_dev_test_terminate(void);

#endif
